/**
 * API Request/Response Type Definitions for Nanobanna Pro
 *
 * This file contains TypeScript interfaces for all backend API endpoints.
 * All endpoints are documented with request/response schemas, validation rules,
 * and HTTP status codes.
 *
 * @see docs/api/README.md - Main API documentation
 * @see docs/api/ENDPOINTS.md - Endpoint catalog
 */

// ============================================================================
// COMMON TYPES
// ============================================================================

/**
 * Standard error response format used across all endpoints
 */
export interface ErrorResponse {
  error: string; // Human-readable error message
}

/**
 * Rate limit exceeded response (HTTP 429)
 */
export interface RateLimitResponse {
  error: 'Too many requests. Please try again later.';
}

/**
 * Standard success response for operations without specific data
 */
export interface SuccessResponse {
  success: true;
  message?: string;
}

// ============================================================================
// AI ROUTES (/api/ai/*)
// ============================================================================
// Authentication: Required for all endpoints
// Rate Limit: 30 requests per minute

// ---------- Chat Endpoint ----------

export interface ChatMessage {
  role: 'user' | 'assistant' | 'system';
  content: string | MessageContent[];
}

export interface MessageContent {
  type: 'text' | 'image_url';
  text?: string; // For type='text'
  image_url?: {
    // For type='image_url'
    url: string; // Data URI or HTTPS URL
  };
}

export interface Tool {
  type: 'function';
  function: {
    name: string; // Function identifier
    description: string; // What the function does
    parameters: {
      // JSON Schema for parameters
      type: 'object';
      properties: Record<string, any>;
      required?: string[];
    };
  };
}

export interface ChatRequest {
  messages: ChatMessage[]; // Required: Conversation history
  model: string; // Required: OpenRouter model ID
  tools?: Tool[]; // Optional: Function calling tools
  tool_choice?: string; // Optional: Tool selection strategy
}

export interface ChatResponseSimple {
  text: string; // Model's text response
}

export interface ChatResponseFull {
  id: string;
  object: 'chat.completion';
  created: number;
  model: string;
  choices: Array<{
    index: number;
    message: {
      role: 'assistant';
      content: string | null;
      tool_calls?: Array<{
        id: string;
        type: 'function';
        function: {
          name: string;
          arguments: string; // JSON string
        };
      }>;
    };
    finish_reason: 'stop' | 'tool_calls' | 'length';
  }>;
  usage?: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

// ---------- Image Generation Endpoint ----------

export interface ImageGenerateRequest {
  prompt: string; // Required: Image description
  model: string; // Required: Replicate model ID
  provider?: 'replicate'; // Optional: Always 'replicate'
  aspect_ratio?: string; // Optional: e.g., "16:9", "4:1", "1:1"
  width?: number; // Optional: Image width
  height?: number; // Optional: Image height
}

export interface ImageGenerateResponse {
  url: string; // Generated image URL (HTTPS)
}

// ---------- Image Edit Endpoint ----------

export interface ImageEditRequest {
  image: string; // Required: Base64 or data URI or HTTPS URL
  mask?: string; // Optional: Mask for inpainting
  prompt: string; // Required: Edit instruction
  provider?: 'openrouter' | 'replicate'; // Optional: Provider preference
  model?: string; // Optional: Specific model override
}

export interface ImageEditResponse {
  url: string; // Edited image URL (HTTPS)
}

// ---------- Image Utility Endpoints ----------

export interface RemoveBackgroundRequest {
  image: string; // Required: Base64, data URI, or HTTPS URL
  model?: string; // Optional: Model override
}

export interface RemoveBackgroundResponse {
  url: string; // Image with removed background (HTTPS)
}

export interface UpscaleRequest {
  image: string; // Required: Image to upscale
  scale?: number; // Optional: Scaling factor (default: 2)
  model?: string; // Optional: Model override
}

export interface UpscaleResponse {
  url: string; // Upscaled image URL (HTTPS)
}

export interface OutpaintRequest {
  image: string; // Required: Source image
  prompt?: string; // Optional: Extension description
  direction?: string; // Optional: Direction (default: "right")
  model?: string; // Optional: Model override
}

export interface OutpaintResponse {
  url: string; // Outpainted image URL (HTTPS)
}

export interface RestoreRequest {
  image: string; // Required: Image with faces to restore
  fidelity?: number; // Optional: Fidelity level (0.0-1.0, default: 0.7)
}

export interface RestoreResponse {
  url: string; // Restored image URL (HTTPS)
}

// ---------- Prompt Enhancement Endpoint ----------

export interface PromptEnhanceContext {
  industry?: string; // e.g., "tech", "finance", "healthcare"
  style?: string; // e.g., "professional", "creative", "minimalist"
  brandColors?: string[]; // e.g., ["#1a73e8", "#34a853"]
}

export interface PromptEnhanceRequest {
  prompt: string; // Required: Original prompt
  context?: PromptEnhanceContext; // Optional: Enhancement context
}

export interface PromptEnhanceResponse {
  enhancedPrompt: string; // Enhanced prompt optimized for image generation
  originalPrompt: string; // Echo of original prompt
}

// ============================================================================
// AUTHENTICATION ROUTES (/api/auth/*)
// ============================================================================

// ---------- Signup Endpoint ----------
// Rate Limit: 3 requests per minute

export interface SignupRequest {
  email: string; // Required: Valid email address
  password: string; // Required: Min 8 characters
}

export interface SignupResponse {
  success: true;
  userId: string; // UUID of created user
  message: 'Verification email sent';
}

// ---------- Login Endpoint ----------
// Rate Limit: 5 requests per minute

export interface LoginRequest {
  email: string; // Required: User email
  password: string; // Required: User password
}

export interface LoginResponse {
  success: true;
  user: {
    id: string; // User UUID
    email: string; // User email
  };
}

// ---------- Logout Endpoint ----------

export interface LogoutResponse {
  success: true;
}

// ---------- Check Username Endpoint ----------

export interface CheckUsernameQuery {
  username: string; // Required: Username to check
}

export interface CheckUsernameResponse {
  available: boolean; // true if username available
}

// ---------- Get Current User Endpoint ----------

export interface AuthMeResponse {
  user: {
    id: string; // User UUID
    email: string; // User email
    username: string; // Username
    createdAt: string; // ISO 8601 timestamp
    emailVerified: boolean; // Email verification status
    profile?: {
      // Optional profile data
      displayName?: string;
      avatar?: string;
      bio?: string;
    };
  };
}

// ---------- Email Verification Endpoint ----------

export interface VerifyEmailRequest {
  token: string; // Required: Verification token from email
}

export interface VerifyEmailResponse {
  success: true;
  message: 'Email verified successfully';
}

// ---------- Password Reset Endpoints ----------
// Rate Limit: 3 requests per minute

export interface ForgotPasswordRequest {
  email: string; // Required: User email
}

export interface ForgotPasswordResponse {
  success: true;
  message: 'Password reset email sent if account exists';
}

export interface ResetPasswordRequest {
  token: string; // Required: Reset token from email
  newPassword: string; // Required: New password (min 8 chars)
}

export interface ResetPasswordResponse {
  success: true;
  message: 'Password reset successfully';
}

// ============================================================================
// CHAT ROUTES (/api/chat/*)
// ============================================================================
// Authentication: Required for all endpoints

// ---------- Create Chat Endpoint ----------

export interface CreateChatRequest {
  title?: string; // Optional: Chat title (default: "New Chat")
  modelId?: string; // Optional: AI model ID
}

export interface CreateChatResponse {
  id: string; // Chat UUID
  userId: string; // Owner user ID
  title: string; // Chat title
  modelId: string | null; // Model ID or null
  createdAt: string; // ISO 8601 timestamp
  updatedAt: string; // ISO 8601 timestamp
}

// ---------- List Chats Endpoint ----------

export interface ListChatsQuery {
  limit?: number; // Optional: Max chats to return (default: 50)
  offset?: number; // Optional: Pagination offset (default: 0)
}

export interface ListChatsResponse {
  chats: Array<{
    id: string;
    userId: string;
    title: string;
    modelId: string | null;
    messageCount: number; // Number of messages in chat
    createdAt: string;
    updatedAt: string;
  }>;
  total: number; // Total chat count (for pagination)
}

// ---------- Get Chat Endpoint ----------

export interface GetChatResponse {
  id: string;
  userId: string;
  title: string;
  modelId: string | null;
  createdAt: string;
  updatedAt: string;
  messages: Array<{
    id: string;
    chatId: string;
    role: 'user' | 'assistant' | 'system';
    content: string;
    createdAt: string;
  }>;
}

// ---------- Add Message Endpoint ----------

export interface AddMessageRequest {
  role: 'user' | 'assistant' | 'system'; // Required: Message role
  content: string; // Required: Message content
}

export interface AddMessageResponse {
  id: string; // Message UUID
  chatId: string; // Parent chat ID
  role: 'user' | 'assistant' | 'system';
  content: string;
  createdAt: string; // ISO 8601 timestamp
}

// ---------- Update Chat Endpoint ----------

export interface UpdateChatRequest {
  title?: string; // Optional: New title
  modelId?: string; // Optional: New model ID
}

export interface UpdateChatResponse {
  id: string;
  userId: string;
  title: string;
  modelId: string | null;
  createdAt: string;
  updatedAt: string; // Updated timestamp
}

// ---------- Delete Chat Endpoint ----------

export interface DeleteChatResponse {
  success: true;
  message: 'Chat deleted successfully';
}

// ---------- Export Chat Endpoint ----------

export interface ExportChatResponse {
  chat: {
    id: string;
    title: string;
    createdAt: string;
    messages: Array<{
      role: 'user' | 'assistant' | 'system';
      content: string;
      timestamp: string;
    }>;
  };
  format: 'json';
}

// ============================================================================
// IMAGE MANAGEMENT ROUTES (/api/images/*)
// ============================================================================
// Authentication: Required for all endpoints

// ---------- Save Image Endpoint ----------

export interface SaveImageRequest {
  url: string; // Required: Image URL
  prompt?: string; // Optional: Generation prompt
  model?: string; // Optional: Model used
  width?: number; // Optional: Image width
  height?: number; // Optional: Image height
  metadata?: Record<string, any>; // Optional: Additional metadata
}

export interface SaveImageResponse {
  id: string; // Image UUID
  userId: string;
  url: string;
  prompt: string | null;
  model: string | null;
  width: number | null;
  height: number | null;
  metadata: Record<string, any> | null;
  createdAt: string; // ISO 8601 timestamp
}

// ---------- List Images Endpoint ----------

export interface ListImagesQuery {
  limit?: number; // Optional: Max images (default: 50)
  offset?: number; // Optional: Pagination offset (default: 0)
  model?: string; // Optional: Filter by model
}

export interface ListImagesResponse {
  images: Array<{
    id: string;
    userId: string;
    url: string;
    prompt: string | null;
    model: string | null;
    width: number | null;
    height: number | null;
    metadata: Record<string, any> | null;
    createdAt: string;
  }>;
  total: number; // Total image count
}

// ---------- Get Image Endpoint ----------

export interface GetImageResponse {
  id: string;
  userId: string;
  url: string;
  prompt: string | null;
  model: string | null;
  width: number | null;
  height: number | null;
  metadata: Record<string, any> | null;
  createdAt: string;
}

// ---------- Update Image Endpoint ----------

export interface UpdateImageRequest {
  prompt?: string; // Optional: Update prompt
  metadata?: Record<string, any>; // Optional: Update metadata
}

export interface UpdateImageResponse {
  id: string;
  userId: string;
  url: string;
  prompt: string | null;
  model: string | null;
  width: number | null;
  height: number | null;
  metadata: Record<string, any> | null;
  createdAt: string;
  updatedAt: string; // Updated timestamp
}

// ---------- Delete Image Endpoint ----------

export interface DeleteImageResponse {
  success: true;
  message: 'Image deleted successfully';
}

// ---------- Batch Delete Images Endpoint ----------

export interface BatchDeleteImagesRequest {
  imageIds: string[]; // Required: Array of image UUIDs
}

export interface BatchDeleteImagesResponse {
  success: true;
  deleted: number; // Number of images deleted
  failed: string[]; // Array of image IDs that failed to delete
}

// ============================================================================
// STORAGE ROUTES (/api/storage/*)
// ============================================================================
// Authentication: Required for all endpoints

// ---------- Upload File Endpoint ----------

export interface UploadFileRequest {
  file: File; // Required: File to upload
  folder?: string; // Optional: Storage folder (default: "uploads")
  public?: boolean; // Optional: Public access (default: false)
}

export interface UploadFileResponse {
  id: string; // File UUID
  url: string; // Public URL
  path: string; // Storage path
  filename: string; // Original filename
  mimeType: string; // File MIME type
  size: number; // File size in bytes
  createdAt: string; // ISO 8601 timestamp
}

// ---------- List Files Endpoint ----------

export interface ListFilesQuery {
  folder?: string; // Optional: Filter by folder
  limit?: number; // Optional: Max files (default: 50)
  offset?: number; // Optional: Pagination offset (default: 0)
}

export interface ListFilesResponse {
  files: Array<{
    id: string;
    url: string;
    path: string;
    filename: string;
    mimeType: string;
    size: number;
    createdAt: string;
  }>;
  total: number; // Total file count
}

// ---------- Delete File Endpoint ----------

export interface DeleteFileResponse {
  success: true;
  message: 'File deleted successfully';
}

// ---------- Storage Quota Endpoint ----------

export interface StorageQuotaResponse {
  used: number; // Bytes used
  total: number; // Total bytes allowed
  percentage: number; // Usage percentage (0-100)
  fileCount: number; // Number of files
}

// ============================================================================
// USER ROUTES (/api/user/*)
// ============================================================================
// Authentication: Required for all endpoints

// ---------- Get Profile Endpoint ----------

export interface UserProfileResponse {
  id: string;
  email: string;
  username: string;
  displayName: string | null;
  avatar: string | null;
  bio: string | null;
  emailVerified: boolean;
  createdAt: string;
  preferences: {
    theme: 'light' | 'dark' | 'auto';
    language: string;
    notifications: boolean;
  } | null;
}

// ---------- Update Profile Endpoint ----------

export interface UpdateProfileRequest {
  displayName?: string; // Optional: Display name
  avatar?: string; // Optional: Avatar URL
  bio?: string; // Optional: Bio (max 500 chars)
}

export interface UpdateProfileResponse {
  id: string;
  email: string;
  username: string;
  displayName: string | null;
  avatar: string | null;
  bio: string | null;
  emailVerified: boolean;
  createdAt: string;
  updatedAt: string;
}

// ---------- Get Preferences Endpoint ----------

export interface UserPreferencesResponse {
  theme: 'light' | 'dark' | 'auto';
  language: string; // e.g., "en", "es", "fr"
  notifications: boolean;
  defaultModel?: string; // Default AI model
  autoSave: boolean;
}

// ---------- Update Preferences Endpoint ----------

export interface UpdatePreferencesRequest {
  theme?: 'light' | 'dark' | 'auto';
  language?: string;
  notifications?: boolean;
  defaultModel?: string;
  autoSave?: boolean;
}

export interface UpdatePreferencesResponse {
  theme: 'light' | 'dark' | 'auto';
  language: string;
  notifications: boolean;
  defaultModel?: string;
  autoSave: boolean;
  updatedAt: string;
}

// ---------- Get API Keys Endpoint ----------

export interface ApiKeysResponse {
  openrouterApiKey: string | null; // Masked: "sk-...abc123"
  replicateApiKey: string | null; // Masked: "r8-...def456"
  hasOpenRouterKey: boolean; // true if key exists
  hasReplicateKey: boolean; // true if key exists
}

// ---------- Set API Keys Endpoint ----------

export interface SetApiKeysRequest {
  openrouterApiKey?: string; // Optional: OpenRouter API key
  replicateApiKey?: string; // Optional: Replicate API key
}

export interface SetApiKeysResponse {
  success: true;
  message: 'API keys updated successfully';
  openrouterApiKey: string | null; // Masked
  replicateApiKey: string | null; // Masked
}

// ---------- Delete Account Endpoint ----------

export interface DeleteAccountRequest {
  password: string; // Required: Confirm with password
  confirmation: 'DELETE'; // Required: Type "DELETE" to confirm
}

export interface DeleteAccountResponse {
  success: true;
  message: 'Account deleted successfully';
}

// ============================================================================
// REPLICATE PROXY ROUTES (/api/replicate/*)
// ============================================================================
// Authentication: Required for all endpoints
// Purpose: Proxy requests to Replicate API with BYOK support

// ---------- Create Prediction Endpoint ----------

export interface ReplicatePredictionRequest {
  version: string; // Required: Model version ID
  input: Record<string, any>; // Required: Model-specific inputs
}

export interface ReplicatePredictionResponse {
  id: string; // Prediction ID
  status: 'starting' | 'processing' | 'succeeded' | 'failed' | 'canceled';
  output: any | null; // Model output (null until succeeded)
  error: string | null; // Error message if failed
  created_at: string;
  started_at: string | null;
  completed_at: string | null;
  urls: {
    get: string; // URL to fetch prediction status
    cancel: string; // URL to cancel prediction
  };
}

// ---------- Get Prediction Endpoint ----------

export interface ReplicateGetPredictionResponse {
  id: string;
  status: 'starting' | 'processing' | 'succeeded' | 'failed' | 'canceled';
  output: any | null;
  error: string | null;
  metrics: {
    predict_time: number | null; // Seconds
  };
  created_at: string;
  started_at: string | null;
  completed_at: string | null;
}

// ---------- Cancel Prediction Endpoint ----------

export interface ReplicateCancelPredictionResponse {
  id: string;
  status: 'canceled';
}

// ---------- Get Model Endpoint ----------

export interface ReplicateModelResponse {
  owner: string;
  name: string;
  description: string;
  latest_version: {
    id: string;
    created_at: string;
    openapi_schema: Record<string, any>;
  };
  url: string;
}

// ---------- Get Account Endpoint ----------

export interface ReplicateAccountResponse {
  username: string;
  name: string | null;
  github_username: string | null;
}

// ============================================================================
// UTILITY TYPES
// ============================================================================

/**
 * HTTP status codes used across the API
 */
export type ApiStatusCode =
  | 200 // OK
  | 201 // Created
  | 204 // No Content
  | 400 // Bad Request
  | 401 // Unauthorized
  | 403 // Forbidden
  | 404 // Not Found
  | 409 // Conflict
  | 429 // Too Many Requests
  | 500 // Internal Server Error
  | 503; // Service Unavailable

/**
 * Rate limit headers returned by the API
 */
export interface RateLimitHeaders {
  'X-RateLimit-Limit': string; // Total requests allowed
  'X-RateLimit-Remaining': string; // Requests remaining
  'X-RateLimit-Reset': string; // Unix timestamp when limit resets
  'Retry-After'?: string; // Seconds until retry (when rate limited)
}

/**
 * Provider types for AI operations
 */
export type AIProvider = 'gemini' | 'openrouter' | 'replicate';

/**
 * Model capabilities
 */
export type ModelCapability =
  | 'text'
  | 'vision'
  | 'thinking'
  | 'image_gen'
  | 'image_edit'
  | 'image_upscale'
  | 'background_removal'
  | 'image_restoration'
  | 'face_enhancement';
